    return d.argmin(axis=1)

def update(self, X, labels):
    new = self.centers.copy()
    for j in range(self.k):
        pts = X[labels == j]
        if len(pts) > 0:
            new[j] = pts.mean(axis=0)
    return new

def fit(self, X):
    rng = np.random.default_rng(self.seed)
    self.centers = X[rng.choice(len(X), self.k, replace=False)]
    for _ in range(self.iters):
        labels = self.assign(X)
        new = self.update(X, labels)
        if np.allclose(new, self.centers):
            break
        self.centers = new
    return self

