def init_centers(self, X):
    rng = np.random.default_rng(self.seed)
    c = [X[rng.integers(len(X))]]
    for _ in range(self.k - 1):
        d = np.min([((X - ci) ** 2).sum(axis=1) for ci in c], axis=0)
        c.append(X[rng.choice(len(X), p=d / d.sum())])
    return np.array(c)

def assign(self, X):
    d = ((X[:, None, :] - self.centers[None]) ** 2).sum(axis=2)
    return d.argmin(axis=1)

def fit(self, X):
    self.centers = self.init_centers(X)
    for _ in range(self.iters):
        labels = self.assign(X)
        self.centers = np.array([X[labels == j].mean(axis=0) for j in range(self.k)])
    return self
